package com.tekwatt.tariff.dto;import com.tekwatt.tariff.entity.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;
public record TariffResponse(UUID id,UUID tenantId,String code,String name,BigDecimal energyPricePerKwh,BigDecimal timePricePerMinute,BigDecimal sessionFee,BigDecimal taxPercent,String currency,TariffStatus status,Instant validFrom,Instant validTo,Instant createdAt,Instant updatedAt){public static TariffResponse from(Tariff t){return new TariffResponse(t.getId(),t.getTenantId(),t.getCode(),t.getName(),t.getEnergyPricePerKwh(),t.getTimePricePerMinute(),t.getSessionFee(),t.getTaxPercent(),t.getCurrency(),t.getStatus(),t.getValidFrom(),t.getValidTo(),t.getCreatedAt(),t.getUpdatedAt());}}
